export default function ClientesForm(){
    return(
        <form>
            <div>
                <div>
                    <label>Nome completo:</label>
                    <input required value={cliente.nome} type="text" onChange={(e)=>{handleChange('nome',e.target.value)}} placeholder="Digite seu nome" />
                </div>
            </div>
        </form>
    )
}